const CACHE="tafy-shell";self.addEventListener("install",()=>{self.skipWaiting()}),self.addEventListener("activate",a=>{a.waitUntil((async()=>{const t=await caches.keys();await Promise.all(t.filter(c=>c!==CACHE).map(c=>caches.delete(c))),await self.clients.claim()})())});const IMMUTABLE=a=>/\/assets\/[^/]+-[A-Za-z0-9_-]+\.(js|wasm|css)$/.test(a.pathname);self.addEventListener("fetch",a=>{const t=a.request;if(t.method!=="GET")return;let c;try{c=new URL(t.url)}catch{return}if(c.origin===self.location.origin)if(IMMUTABLE(c))a.respondWith((async()=>{const n=await caches.match(t);if(n)return n;const s=await fetch(t);return s.ok&&(await caches.open(CACHE)).put(t,s.clone()),s})());else{const n=async()=>await caches.match("./",{ignoreSearch:!0})||await caches.match("./index.html");a.respondWith((async()=>{const s=t.mode==="navigate";try{const e=await fetch(t);return e.ok?((await caches.open(CACHE)).put(t,e.clone()),e):s&&await n()||e}catch{const e=s?await n():await caches.match(t);if(e)return e;throw new Error("offline and uncached")}})())}});
